package it.comune.trieste.ouf.udp;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Types;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class LakeShadowRebuildService {
  private final JdbcClient db;private final LakeObjectStoragePort storage;private final ObjectMapper json;
  public LakeShadowRebuildService(JdbcClient db,org.springframework.beans.factory.ObjectProvider<LakeObjectStoragePort> storage,ObjectMapper json){this.db=db;this.storage=storage.orderedStream().findFirst().orElse(null);this.json=json;}

  @Transactional public Plan plan(String tier,TrustedHumanContext actor){actor.require("lake.shadow.plan");if(!Set.of("RAW","NORMALIZED","CURATED","EXPORT").contains(tier))throw new IllegalArgumentException("UDP_LAKE_TIER_INVALID");List<Map<String,Object>> objects=db.sql("select lake_object_id,content_hash,logical_size_bytes,locator from ouf_udp.lake_object where tenant_id=:tenant and tier=:tier and state in('VERIFIED','COMPACTED','COLD') order by lake_object_id").param("tenant",actor.tenantId()).param("tier",tier).query().listOfRows();if(objects.isEmpty())throw new IllegalStateException("UDP_LAKE_SHADOW_EMPTY");UUID plan=UUID.randomUUID();String digest=digest(objects);db.sql("insert into ouf_udp.lake_shadow_rebuild_plan(plan_id,tenant_id,tier,state,expected_object_count,baseline_digest,created_by_subject,correlation_id) values(:id,:tenant,:tier,'DRAFT',:count,:digest,:subject,:correlation)").param("id",plan).param("tenant",actor.tenantId()).param("tier",tier).param("count",objects.size()).param("digest",digest).param("subject",actor.subject()).param("correlation",actor.correlationId()).update();for(var object:objects)db.sql("insert into ouf_udp.lake_shadow_rebuild_entry(plan_id,lake_object_id,source_locator,source_locator_fingerprint,source_hash,source_size_bytes,state) values(:plan,:object,:locator,:fingerprint,:hash,:size,'PENDING')").param("plan",plan).param("object",object.get("lake_object_id")).param("locator",object.get("locator")).param("fingerprint",fingerprint(String.valueOf(object.get("locator")))).param("hash",object.get("content_hash")).param("size",object.get("logical_size_bytes")).update();event(plan,"SHADOW_REBUILD_PLANNED",actor.actorType(),actor.subject(),actor.authorizationDecisionRef(),actor.correlationId(),Map.of("tier",tier,"objectCount",objects.size()));return get(plan,actor.tenantId());}

  @Transactional public Optional<BuildClaim> claim(String worker,long leaseSeconds){long lease=Math.max(60,leaseSeconds);return db.sql("with candidate as(select plan_id from ouf_udp.lake_shadow_rebuild_plan where state='DRAFT' or (state='BUILDING' and lease_until<transaction_timestamp()) order by created_at,plan_id for update skip locked limit 1) update ouf_udp.lake_shadow_rebuild_plan p set state='BUILDING',version=version+1,lease_owner=:worker,lease_until=transaction_timestamp()+(:lease*interval '1 second'),lease_generation=lease_generation+1 from candidate c where p.plan_id=c.plan_id returning p.plan_id,p.lease_generation,p.correlation_id").param("worker",worker).param("lease",lease).query((rs,n)->new BuildClaim(rs.getObject(1,UUID.class),worker,rs.getLong(2),rs.getString(3),lease)).optional();}

  public Plan build(BuildClaim claim){requireStorage();UUID planId=claim.planId();try{List<Map<String,Object>> entries=db.sql("select lake_object_id,source_locator,source_hash,source_size_bytes from ouf_udp.lake_shadow_rebuild_entry where plan_id=:id order by lake_object_id").param("id",planId).query().listOfRows();for(var entry:entries){renew(claim);UUID object=(UUID)entry.get("lake_object_id");String hash=String.valueOf(entry.get("source_hash")),shadow="shadow/"+planId+"/"+object;if("VERIFIED".equals(db.sql("select state from ouf_udp.lake_shadow_rebuild_entry where plan_id=:plan and lake_object_id=:object").param("plan",planId).param("object",object).query(String.class).single()))continue;byte[] content=storage.read(String.valueOf(entry.get("source_locator")));var put=storage.put(shadow,content,"application/octet-stream",hash);var head=storage.head(shadow).orElseThrow(()->new IllegalStateException("UDP_LAKE_SHADOW_MISSING"));if(!put.durable()||!hash.equals(put.contentHash())||!hash.equals(head.contentHash())||((Number)entry.get("source_size_bytes")).longValue()!=head.sizeBytes())throw new IllegalStateException("UDP_LAKE_SHADOW_VERIFY_FAILED");int checkpoint=db.sql("update ouf_udp.lake_shadow_rebuild_entry e set state='VERIFIED',shadow_locator=:shadow,verified_at=transaction_timestamp(),verified_generation=:generation where plan_id=:plan and lake_object_id=:object and state='PENDING' and exists(select 1 from ouf_udp.lake_shadow_rebuild_plan p where p.plan_id=e.plan_id and p.state='BUILDING' and p.lease_owner=:worker and p.lease_generation=:generation and p.lease_until>transaction_timestamp())").param("shadow",shadow).param("generation",claim.generation()).param("plan",planId).param("object",object).param("worker",claim.worker()).update();if(checkpoint!=1)throw new IllegalStateException("UDP_LAKE_SHADOW_LEASE_LOST");}renew(claim);List<Map<String,Object>> verified=db.sql("select lake_object_id,source_hash content_hash,source_size_bytes logical_size_bytes from ouf_udp.lake_shadow_rebuild_entry where plan_id=:id and state='VERIFIED' order by lake_object_id").param("id",planId).query().listOfRows();String shadowDigest=digest(verified);int ready=db.sql("update ouf_udp.lake_shadow_rebuild_plan set state='READY',version=version+1,verified_object_count=expected_object_count,shadow_digest=:digest,completed_at=transaction_timestamp(),lease_owner=null,lease_until=null where plan_id=:id and state='BUILDING' and lease_owner=:worker and lease_generation=:generation and lease_until>transaction_timestamp() and (select count(*) from ouf_udp.lake_shadow_rebuild_entry where plan_id=:id and state='VERIFIED')=expected_object_count and baseline_digest=:digest").param("digest",shadowDigest).param("id",planId).param("worker",claim.worker()).param("generation",claim.generation()).update();if(ready!=1)throw new IllegalStateException("UDP_LAKE_SHADOW_VALIDATION_FAILED");event(planId,"SHADOW_REBUILD_READY","SERVICE_IDENTITY",claim.worker(),"",claim.correlation(),Map.of("verified",entries.size()));return getUnscoped(planId);}catch(RuntimeException failure){int failed=db.sql("update ouf_udp.lake_shadow_rebuild_plan set state='FAILED',version=version+1,safe_error_code=:code,lease_owner=null,lease_until=null where plan_id=:id and state='BUILDING' and lease_owner=:worker and lease_generation=:generation").param("code",safe(failure)).param("id",planId).param("worker",claim.worker()).param("generation",claim.generation()).update();if(failed==1)event(planId,"SHADOW_REBUILD_FAILED","SERVICE_IDENTITY",claim.worker(),"",claim.correlation(),Map.of("safeErrorCode",safe(failure)));throw failure;}}

  private void renew(BuildClaim claim){int renewed=db.sql("update ouf_udp.lake_shadow_rebuild_plan set lease_until=transaction_timestamp()+(:lease*interval '1 second'),version=version+1 where plan_id=:id and state='BUILDING' and lease_owner=:worker and lease_generation=:generation and lease_until>transaction_timestamp()").param("lease",claim.leaseSeconds()).param("id",claim.planId()).param("worker",claim.worker()).param("generation",claim.generation()).update();if(renewed!=1)throw new IllegalStateException("UDP_LAKE_SHADOW_LEASE_LOST");}

  @Transactional public Plan cutover(UUID planId,long expectedVersion,String reason,TrustedHumanContext actor){actor.require("lake.shadow.cutover");if(reason==null||reason.isBlank())throw new IllegalArgumentException("UDP_REASON_REQUIRED");Plan plan=get(planId,actor.tenantId());if(!"READY".equals(plan.state())||plan.version()!=expectedVersion)throw new ResponseStatusException(HttpStatus.CONFLICT,"UDP_LAKE_SHADOW_VERSION_CONFLICT");List<Map<String,Object>> entries=db.sql("select e.lake_object_id,e.source_locator,e.shadow_locator,e.source_hash,o.locator current_locator,o.content_hash current_hash,o.state,o.state_version from ouf_udp.lake_shadow_rebuild_entry e join ouf_udp.lake_object o on o.lake_object_id=e.lake_object_id where e.plan_id=:id and e.state='VERIFIED' and o.tenant_id=:tenant order by e.lake_object_id for update of o").param("id",planId).param("tenant",actor.tenantId()).query().listOfRows();if(entries.size()!=plan.expectedObjectCount())throw new IllegalStateException("UDP_LAKE_SHADOW_REFERENCE_GATE_FAILED");for(var entry:entries){if(!Objects.equals(entry.get("source_locator"),entry.get("current_locator"))||!Objects.equals(entry.get("source_hash"),entry.get("current_hash"))||!Set.of("VERIFIED","COMPACTED","COLD").contains(String.valueOf(entry.get("state"))))throw new IllegalStateException("UDP_LAKE_SHADOW_REFERENCE_GATE_FAILED");int n=db.sql("update ouf_udp.lake_object set previous_locator=locator,locator=:shadow,state_version=state_version+1 where lake_object_id=:object and locator=:source and content_hash=:hash and state_version=:version").param("shadow",entry.get("shadow_locator")).param("object",entry.get("lake_object_id")).param("source",entry.get("source_locator")).param("hash",entry.get("source_hash")).param("version",entry.get("state_version")).update();if(n!=1)throw new IllegalStateException("UDP_LAKE_SHADOW_REFERENCE_GATE_FAILED");db.sql("update ouf_udp.lake_shadow_rebuild_entry set state='CUTOVER' where plan_id=:plan and lake_object_id=:object and state='VERIFIED'").param("plan",planId).param("object",entry.get("lake_object_id")).update();}int done=db.sql("update ouf_udp.lake_shadow_rebuild_plan set state='CUTOVER',version=version+1,cutover_at=transaction_timestamp(),cutover_by_subject=:subject,authorization_decision_ref=:decision,reason=:reason where plan_id=:id and tenant_id=:tenant and state='READY' and version=:version").param("subject",actor.subject()).param("decision",actor.authorizationDecisionRef()).param("reason",reason).param("id",planId).param("tenant",actor.tenantId()).param("version",expectedVersion).update();if(done!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"UDP_LAKE_SHADOW_VERSION_CONFLICT");event(planId,"SHADOW_REBUILD_CUTOVER",actor.actorType(),actor.subject(),actor.authorizationDecisionRef(),actor.correlationId(),Map.of("reason",reason,"objectCount",entries.size()));return get(planId,actor.tenantId());}

  @Transactional public Plan rollback(UUID planId,long expectedVersion,String reason,TrustedHumanContext actor){actor.require("lake.shadow.rollback");if(reason==null||reason.isBlank())throw new IllegalArgumentException("UDP_REASON_REQUIRED");Plan plan=get(planId,actor.tenantId());if(!"CUTOVER".equals(plan.state())||plan.version()!=expectedVersion)throw new ResponseStatusException(HttpStatus.CONFLICT,"UDP_LAKE_SHADOW_VERSION_CONFLICT");List<Map<String,Object>> entries=db.sql("select e.lake_object_id,e.source_locator,e.shadow_locator,o.locator current_locator,o.previous_locator,o.state_version from ouf_udp.lake_shadow_rebuild_entry e join ouf_udp.lake_object o on o.lake_object_id=e.lake_object_id where e.plan_id=:id and e.state='CUTOVER' and o.tenant_id=:tenant order by e.lake_object_id for update of o").param("id",planId).param("tenant",actor.tenantId()).query().listOfRows();if(entries.size()!=plan.expectedObjectCount())throw new IllegalStateException("UDP_LAKE_SHADOW_ROLLBACK_GATE_FAILED");for(var entry:entries){if(!Objects.equals(entry.get("shadow_locator"),entry.get("current_locator"))||!Objects.equals(entry.get("source_locator"),entry.get("previous_locator")))throw new IllegalStateException("UDP_LAKE_SHADOW_ROLLBACK_GATE_FAILED");int n=db.sql("update ouf_udp.lake_object set locator=:source,previous_locator=:shadow,state_version=state_version+1 where lake_object_id=:object and locator=:shadow and previous_locator=:source and state_version=:version").param("source",entry.get("source_locator")).param("shadow",entry.get("shadow_locator")).param("object",entry.get("lake_object_id")).param("version",entry.get("state_version")).update();if(n!=1)throw new IllegalStateException("UDP_LAKE_SHADOW_ROLLBACK_GATE_FAILED");db.sql("update ouf_udp.lake_shadow_rebuild_entry set state='ROLLED_BACK' where plan_id=:plan and lake_object_id=:object and state='CUTOVER'").param("plan",planId).param("object",entry.get("lake_object_id")).update();}int done=db.sql("update ouf_udp.lake_shadow_rebuild_plan set state='ROLLED_BACK',version=version+1,rolled_back_at=transaction_timestamp(),rolled_back_by_subject=:subject,authorization_decision_ref=:decision,reason=:reason where plan_id=:id and tenant_id=:tenant and state='CUTOVER' and version=:version").param("subject",actor.subject()).param("decision",actor.authorizationDecisionRef()).param("reason",reason).param("id",planId).param("tenant",actor.tenantId()).param("version",expectedVersion).update();if(done!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"UDP_LAKE_SHADOW_VERSION_CONFLICT");event(planId,"SHADOW_REBUILD_ROLLED_BACK",actor.actorType(),actor.subject(),actor.authorizationDecisionRef(),actor.correlationId(),Map.of("reason",reason,"objectCount",entries.size()));return get(planId,actor.tenantId());}

  public Plan get(UUID id,String tenant){return db.sql("select plan_id,tenant_id,tier,state,version,expected_object_count,verified_object_count,baseline_digest,shadow_digest,safe_error_code from ouf_udp.lake_shadow_rebuild_plan where plan_id=:id and tenant_id=:tenant").param("id",id).param("tenant",tenant).query((rs,n)->map(rs,n)).list().stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"UDP_LAKE_SHADOW_NOT_FOUND"));}
  private Plan getUnscoped(UUID id){return db.sql("select plan_id,tenant_id,tier,state,version,expected_object_count,verified_object_count,baseline_digest,shadow_digest,safe_error_code from ouf_udp.lake_shadow_rebuild_plan where plan_id=:id").param("id",id).query((rs,n)->map(rs,n)).single();}
  private static Plan map(java.sql.ResultSet rs,int n)throws java.sql.SQLException{return new Plan(rs.getObject("plan_id",UUID.class),rs.getString("tenant_id"),rs.getString("tier"),rs.getString("state"),rs.getLong("version"),rs.getInt("expected_object_count"),rs.getInt("verified_object_count"),rs.getString("baseline_digest"),rs.getString("shadow_digest"),rs.getString("safe_error_code"));}
  private void requireStorage(){if(storage==null)throw new IllegalStateException("UDP_LAKE_STORAGE_REQUIRED");}
  private String digest(List<Map<String,Object>> rows){String value=rows.stream().map(x->x.get("lake_object_id")+":"+x.get("content_hash")+":"+x.get("logical_size_bytes")).reduce((a,b)->a+"|"+b).orElseThrow();return hex(value);}
  private static String fingerprint(String value){return hex(value).substring(0,24);}
  private static String hex(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
  private static String safe(RuntimeException failure){String message=failure.getMessage();return message!=null&&message.matches("UDP_[A-Z0-9_]+")?message:"UDP_LAKE_SHADOW_FAILED";}
  private void event(UUID plan,String type,String actorType,String subject,String decision,String correlation,Map<String,Object> detail){try{db.sql("insert into ouf_udp.lake_shadow_rebuild_event(event_id,plan_id,event_type,actor_type,actor_subject,authorization_decision_ref,correlation_id,safe_detail) values(gen_random_uuid(),:plan,:type,:actorType,:subject,:decision,:correlation,cast(:detail as jsonb))").param("plan",plan).param("type",type).param("actorType",actorType).param("subject",subject).param("decision",decision,Types.VARCHAR).param("correlation",correlation).param("detail",json.writeValueAsString(detail)).update();}catch(Exception e){throw new IllegalStateException(e);}}
  public record Plan(UUID id,String tenantId,String tier,String state,long version,int expectedObjectCount,int verifiedObjectCount,String baselineDigest,String shadowDigest,String safeErrorCode){}
  public record BuildClaim(UUID planId,String worker,long generation,String correlation,long leaseSeconds){}
}
